# Writes tests/headless/lib/ironcalc_fixtures.ts: the IronCalc workbooks in
# third_party/ironcalc/fixtures/xlsx/ (copied unchanged, see that folder's
# PROVENANCE.md) as base64, since the headless harness reads modules, not files.
#   python3 tests/headless/lib/mkironcalc.py
import base64, os
here = os.path.dirname(os.path.abspath(__file__))
src = os.path.join(here, "..", "..", "..", "third_party", "ironcalc", "fixtures", "xlsx")
out = ["// Generated by mkironcalc.py from third_party/ironcalc/fixtures/xlsx/*.xlsx",
       "// (IronCalc, MIT; third_party/ironcalc/PROVENANCE.md). Do not edit.", ""]
for f in sorted(os.listdir(src)):
    if f.endswith(".xlsx"):
        name = os.path.splitext(f)[0].upper()
        out.append('export const %s = "%s"; // %s' % (name, base64.b64encode(open(os.path.join(src, f), "rb").read()).decode(), f))
open(os.path.join(here, "ironcalc_fixtures.ts"), "w").write("\n".join(out) + "\n")
